-- A shared vocabulary for what small businesses here actually sell.
--
-- Two problems, one table. Onboarding a shop means typing hundreds of products
-- by hand, which is the real reason somebody gives up in the first ten minutes.
-- And the same item entered as "Milk 1L", "Maziwa", "maziwa lita moja" and
-- "MILK 1 LITRE" cannot be compared across shops, or reported on honestly even
-- within one.
--
-- Entries are deliberately generic product plus pack size, never brand. Brands
-- multiply this list many times over and can arrive later as a second field.
-- The aliases carry the Swahili, the Sheng and the spellings people type.
--
-- `business_types` is what keeps this usable. A pharmacy must not be offered
-- maziwa and a hardware must not be offered sukuma wiki, so suggestions are
-- ranked by the shop's own trade first. An entry can belong to several: a duka
-- and a bar both sell cigarettes.
--
-- `kind` separates goods from services. A kinyozi sells haircuts, which have a
-- price and no stock level. This is a label on the vocabulary only; it does not
-- reintroduce the services branching that was deliberately stripped in August.

CREATE TABLE IF NOT EXISTS public.canonical_products (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  name TEXT NOT NULL UNIQUE,
  category TEXT NOT NULL,
  pack_size TEXT,
  kind TEXT NOT NULL DEFAULT 'goods' CHECK (kind IN ('goods', 'service')),
  business_types TEXT[] NOT NULL DEFAULT '{}',
  aliases TEXT[] NOT NULL DEFAULT '{}',
  created_at TIMESTAMPTZ NOT NULL DEFAULT now()
);

-- Reference data, not shop data: every signed-in user reads the same rows and
-- nobody writes them from a client. Growing the list is a migration or a
-- service-role job, so one shop can never reshape the vocabulary for everyone.
ALTER TABLE public.canonical_products ENABLE ROW LEVEL SECURITY;

DROP POLICY IF EXISTS "Anyone signed in can read the catalogue" ON public.canonical_products;
CREATE POLICY "Anyone signed in can read the catalogue"
  ON public.canonical_products FOR SELECT
  TO authenticated
  USING (true);

-- pg_trgm is for matching names already typed, in bulk, later. Live suggestions
-- are matched on the client so they keep working on a bad connection.
CREATE EXTENSION IF NOT EXISTS pg_trgm WITH SCHEMA extensions;
CREATE INDEX IF NOT EXISTS canonical_products_name_trgm
  ON public.canonical_products USING gin (name extensions.gin_trgm_ops);
CREATE INDEX IF NOT EXISTS canonical_products_business_types_idx
  ON public.canonical_products USING gin (business_types);

-- The link from a shop's own product to the shared vocabulary.
--
-- ON DELETE SET NULL, never CASCADE: retiring a catalogue entry must not delete
-- somebody's product. Losing the link is recoverable, losing the stock record
-- is not.
ALTER TABLE public.products
  ADD COLUMN IF NOT EXISTS canonical_id UUID REFERENCES public.canonical_products(id) ON DELETE SET NULL;

-- How the link was made, which decides how far it can be trusted. 'chosen'
-- means a person tapped the suggestion. 'matched' means we guessed. Only
-- 'chosen' should ever be treated as ground truth.
ALTER TABLE public.products
  ADD COLUMN IF NOT EXISTS canonical_source TEXT
  CHECK (canonical_source IS NULL OR canonical_source IN ('chosen', 'matched'));

CREATE INDEX IF NOT EXISTS products_canonical_id_idx ON public.products (canonical_id);

ON CONFLICT (name) DO UPDATE
  SET category = EXCLUDED.category,
      pack_size = EXCLUDED.pack_size,
      kind = EXCLUDED.kind,
      business_types = EXCLUDED.business_types,
      aliases = EXCLUDED.aliases;
